2229: function Get-TomlString {
2230:     param($Table, [string]$Key)
2231:     if (-not $Table -or -not $Table.Entries.ContainsKey($Key)) { return [pscustomobject]@{ Present = $false; Value = ''; Line = 0; Reason = '' } }
2232:     $e = $Table.Entries[$Key]
2233:     $why = ''
2234:     if (-not $e.Supported) { $why = $e.Reason }
2235:     elseif ($e.Kind -ne 'string') { $why = "'$Key' at line $($e.Line) of the Codex config is a $($e.Kind), not a string" }
2236:     return [pscustomobject]@{ Present = $true; Value = [string]$e.Value; Line = $e.Line; Reason = $why }
2237: }
