2318: # base_url as the provider identity sees it: scheme and host lowercased, credentials
2319: # (user:pass@) dropped, path as written, no trailing slash. { Url; HostName }.
2320: function ConvertTo-CanonicalBaseUrl {
2321:     param([string]$Url)
2322:     $u = ([string]$Url).Trim()
2323:     $m = [regex]::Match($u, '^([A-Za-z][A-Za-z0-9+.-]*)://([^/?#]*)(.*)$')
2324:     if (-not $m.Success) { return [pscustomobject]@{ Url = $u.TrimEnd([char]'/'); HostName = '' } }
2325:     $scheme = $m.Groups[1].Value.ToLowerInvariant()
2326:     $authority = $m.Groups[2].Value
2327:     $at = $authority.LastIndexOf([char]'@')
2328:     if ($at -ge 0) { $authority = $authority.Substring($at + 1) }
2329:     $authority = $authority.ToLowerInvariant()
2330:     $hostName = $authority
2331:     if ($hostName.StartsWith('[')) {
2332:         $close = $hostName.IndexOf([char]']')
2333:         if ($close -gt 0) { $hostName = $hostName.Substring(0, $close + 1) }
2334:     } else {
2335:         $hostName = $hostName -replace ':[0-9]*$', ''
2336:     }
2337:     return [pscustomobject]@{ Url = ("${scheme}://$authority" + $m.Groups[3].Value).TrimEnd([char]'/'); HostName = $hostName }
2338: }
