2285: # Can the scanner establish whether model_providers.<Name> is declared at all? '' = yes
2286: # (it is a plain table, or nothing declares it); otherwise the reason. A TOML value at key
2287: # path P only defines keys below P, so what can hide a declaration of
2288: # model_providers.<Name> is a construct at `model_providers` itself (an inline table,
2289: # array or string value; a dotted key `model_providers.<x> = ...` written from the top
2290: # level; an array of tables; a table defined twice) or an entry <Name> inside a
2291: # [model_providers] table that is not a sub-table header (an inline table, a dotted key,
2292: # a multi-line string, even a plain value). A construct under model_providers.<other>
2293: # cannot declare <Name> and does not count.
2294: function Get-ProviderSetProblem {
2295:     param($Config, [string]$Name)
2296:     $top = $Config.Tables['']
2297:     # (a top-level dotted key model_providers.<x>... is judged by the table it writes
2298:     # into, which the scanner marked: [model_providers] itself, or <x>'s table)
2299:     if ($top -and $top.Entries.ContainsKey('model_providers') -and $top.Entries['model_providers'].Kind -ne 'dotted key') {
2300:         $e = $top.Entries['model_providers']
2301:         $why = $e.Reason
2302:         if (-not $why) { $why = "model_providers at line $($e.Line) is a $($e.Kind), not a table of providers" }
2303:         return $why
2304:     }
2305:     if ($Config.Tables.ContainsKey('model_providers')) {
2306:         $mp = $Config.Tables['model_providers']
2307:         if (-not $mp.Ok) { return $mp.Reason }
2308:         if ($mp.Entries.ContainsKey($Name)) {
2309:             $e = $mp.Entries[$Name]
2310:             $why = $e.Reason
2311:             if (-not $why) { $why = "[model_providers] declares $Name at line $($e.Line) as a $($e.Kind), not as a table" }
