2340: # Endpoint identity of a usable provider table: { Compat; HostName; BaseUrl; WireApi;
2341: # Display; Config; Error }. Compat = 'cc-provider-v1|base_url=<canonical>|wire_api=<v>'.
2342: # An absent wire_api is 'default' there - no protocol is asserted, and adding the key
2343: # later is a detected change - and provider_config then has no wire_api key. An absent
2344: # base_url is '' (Codex's own default endpoint, not asserted either).
2345: # Config = the table without secret-like keys, sorted by key, base_url without
2346: # credentials and query values (audit metadata, never compared; the fingerprint covers
2347: # the full canonical URL).
2348: function Get-ProviderEndpoint {
2349:     param($Table, [string]$TableName, [string]$Where)
2350:     $r = [pscustomobject]@{ Compat = ''; HostName = ''; BaseUrl = ''; WireApi = ''; Display = ''; Config = (New-Object PSObject); Error = '' }
2351:     $bu = Get-TomlString -Table $Table -Key 'base_url'
2352:     $wa = Get-TomlString -Table $Table -Key 'wire_api'
2353:     if ($bu.Reason) { $r.Error = "$TableName in $Where is not usable - $($bu.Reason)"; return $r }
2354:     if ($wa.Reason) { $r.Error = "$TableName in $Where is not usable - $($wa.Reason)"; return $r }
2355:     $cu = ConvertTo-CanonicalBaseUrl $bu.Value
2356:     $wire = 'default'
2357:     $wireLabel = '(default)'
2358:     if ($wa.Present) { $wire = $wa.Value.Trim(); $wireLabel = $wire }
2359:     $audit = ($cu.Url -replace '\?.*$', '?...')
2360:     $r.Compat = "cc-provider-v1|base_url=$($cu.Url)|wire_api=$wire"
2361:     $r.HostName = $cu.HostName
2362:     $r.BaseUrl = $cu.Url
2363:     $r.WireApi = $wireLabel
2364:     $r.Display = "endpoint $(if ($audit) { $audit } else { '(default)' }), wire_api: $wireLabel"
2365:     $keys = [string[]]@($Table.Entries.Keys)
2366:     [Array]::Sort($keys, [StringComparer]::Ordinal)
2367:     foreach ($key in $keys) {
2368:         if ($key -match $script:SecretKeyPattern) { continue }
2369:         $e = $Table.Entries[$key]
2370:         $val = $e.Value
2371:         if ($key -ceq 'base_url') { $val = $audit }
2372:         elseif ($e.Kind -eq 'boolean') { $val = ($e.Value -ceq 'true') }
2373:         elseif ($e.Kind -eq 'integer') { $n = [long]0; if ([long]::TryParse(($e.Value -replace '_', ''), [ref]$n)) { $val = $n } }
2374:         $r.Config | Add-Member -NotePropertyName $key -NotePropertyValue $val
2375:     }
2376:     return $r
2377: }
