2825: # { Requested; Sent; Mapping; Caps; Basis; Error }
2826: function Resolve-EffortPlan {
2827:     param($Identity, [string]$Requested, [string]$Native = '')
2828:     $plan = [pscustomobject]@{ Requested = $Requested; Sent = ''; Mapping = ''; Caps = $script:EffortCapsVersion; Basis = ''; Error = '' }
2829:     if ($Native) {
2830:         $plan.Requested = $Native; $plan.Sent = $Native; $plan.Mapping = 'native'; $plan.Basis = '-NativeEffort, sent verbatim'
2831:         return $plan
2832:     }
2833:     $hostName = [string]$Identity.HostName
2834:     $model = [string]$Identity.Model
2835:     $cap = $null
2836:     if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) { $cap = $script:EffortCaps[$hostName] }
2837:     if ($cap -and $cap.Vocabulary -eq 'model-tier') {
2838:         # An engine whose model id carries the reasoning tier: nothing is sent.
2839:         $plan.Sent = $null
2840:         $plan.Mapping = 'model-tier'
2841:         $plan.Basis = "$($script:EffortCapsVersion): engine $($hostName -replace '^engine:', ''), the tier is part of the model id"
2842:         return $plan
2843:     }
2844:     if (-not $cap) {
2845:         $hostLabel = if ($hostName) { $hostName } else { 'unknown-host' }
2846:         # Ordinal order: the same list on Windows PowerShell 5.1 (NLS ignores '-') and pwsh 7 (ICU).
2847:         $declaredHosts = [string[]]@($script:EffortCaps.Keys | Where-Object { $_ -notlike 'engine:*' })
2848:         [Array]::Sort($declaredHosts, [StringComparer]::Ordinal)
2849:         $declared = $declaredHosts -join ', '
2850:         $plan.Error = "no effort vocabulary declared for $hostLabel ($($script:EffortCapsVersion) declares $declared); pass -NativeEffort <value> to send a value verbatim"
2851:         return $plan
2852:     }
2853:     if (($null -ne $cap.Models) -and (($Identity.ModelSource -eq 'unknown') -or -not ($cap.Models -ccontains $model))) {
2854:         $plan.Error = "no effort vocabulary declared for model '$model' on $hostName ($($script:EffortCapsVersion) declares: $($cap.Models -join ', ')); pass -NativeEffort <value> to send a value verbatim"
2855:         return $plan
2856:     }
2857:     $v = $null
2858:     if ($script:EffortVocabularies.ContainsKey([string]$cap.Vocabulary)) { $v = $script:EffortVocabularies[[string]$cap.Vocabulary] }
2859:     if ($null -eq $v) {
2860:         # (wave 23, D10) a caps row whose vocabulary is not declared: loud, never an empty mapping
2861:         $plan.Error = "$($script:EffortCapsVersion) names the effort vocabulary '$($cap.Vocabulary)' for $hostName, but no such vocabulary is declared (a bridge defect); pass -NativeEffort <value> to send a value verbatim"
2862:         return $plan
2863:     }
2864:     $plan.Sent = $v.Map[$Requested]
2865:     $plan.Mapping = $v.Mapping
2866:     $plan.Basis = if ($null -eq $cap.Models) { "$($script:EffortCapsVersion): $hostName, any model" } else { "$($script:EffortCapsVersion): $hostName, $model" }
2867:     return $plan
2868: }
