2884: # The clock of the peak evaluations. TEST HOOK: CODEX_CONSULT_NOW = one or more ISO
2885: # timestamps with an offset, comma-separated; the k-th evaluation of a run uses the k-th
2886: # (the last one repeats), so a test can put the early check off-peak and the launch-time
2887: # check inside the window. Unset: the system clock. { Now (DateTimeOffset); Iso; FromEnv;
2888: # Error }. -Peek reads the value the next evaluation would get without consuming it (the
2889: # endpoint-health reading of the preflight and codex-providers.ps1 use it).
2890: $script:ConsultClockCalls = 0
2891: function Get-ConsultClock {
2892:     param([switch]$Peek)
2893:     $raw = (Get-TestHookValue 'CODEX_CONSULT_NOW')
2894:     $call = $script:ConsultClockCalls
2895:     if (-not $Peek) { $script:ConsultClockCalls++ }
2896:     if (-not $raw.Trim()) {
2897:         $n = [DateTimeOffset]::Now
2898:         return [pscustomobject]@{ Now = $n; Iso = $n.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $false; Error = '' }
2899:     }
2900:     $items = @($raw.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2901:     $parsed = New-Object System.Collections.Generic.List[DateTimeOffset]
2902:     foreach ($item in $items) {
2903:         $dto = [DateTimeOffset]::MinValue
2904:         if ($item -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?([+-][0-9]{2}:[0-9]{2}|Z)$' -or -not [DateTimeOffset]::TryParse($item, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dto)) {
2905:             return [pscustomobject]@{ Now = $null; Iso = ''; FromEnv = $true; Error = "CODEX_CONSULT_NOW='$raw' is malformed: bad token '$item' (a test hook: ISO timestamps with an offset, e.g. 2026-09-24T13:59:59+08:00, comma-separated)" }
2906:         }
2907:         $parsed.Add($dto)
2908:     }
2909:     $pick = $parsed[[Math]::Min($call, $parsed.Count - 1)]
2910:     return [pscustomobject]@{ Now = $pick; Iso = $pick.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $true; Error = '' }
2911: }
