6314:     $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
6315:     if ($quota -and -not $quota.Ok) {
6316:         if ($null -ne $quota.RetryAfter) {
6317:             if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
6318:         } elseif ($quota.Until.UtcDateTime -gt $UtcNow) {
6319:             $h.Quota = $quota
6320:         }
6321:     }
6322:     $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
6323:     $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
6324:     $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
6325:     if (-not $h.LastLimit -and $h.Quota) { $h.LastLimit = $h.Quota }
6326:     if (-not $h.LastFailure -and $h.Quota) { $h.LastFailure = $h.Quota }
6327:     $h.RecentUsable = @($sorted | Where-Object { $_.Ok -and $_.Age -le 60 }) | Select-Object -First 1
6328:     return $h
6329: }
