6331: # ----------------------------------------------------------------------------- machine-wide endpoint health (wave 26b, D13 - ROADMAP R20)
6332: #
6333: # ONE file per machine, <codex home>/codex-consult-health.json (CODEX_CONSULT_HEALTH=<path> names
6334: # another; CODEX_CONSULT_HEALTH=none: no file - read nor written), so that the repositories of
6335: # one machine see each other's endpoint outcomes and running members:
6336: #   { "health_version": 1,
6337: #     "endpoints": [ { "endpoint": "<provider fingerprint>", "class": "ok" | "<a provider failure
6338: #                      class>", "kind": "burst" | "", "until": "<iso>" | null, "retry_after": "<the
6339: #                      reset time the provider named>" | null, "repo": "<repository root>", "when":
6340: #                      "<iso>", "message": "<the failure's message, cut to 200>"[, "quota_mark": {
6341: #                      "class": "quota", "kind", "until", "retry_after", "message", "when" } - (wave
6342: #                      29b, E15) on an "ok" record whose turn saw a rejecting rate-limit event] } ],
6343: #     "running":   [ { "endpoint": "<fingerprint>", "label": "<provider label>", "pid": <the run's
6344: #                      bridge pid>, "start_time": "<its start>", "repo": "...", "task": "...", "nn":
6345: #                      "<NN>", "panel": "<panel id or ''>", "since": "<iso>"[, "plan": "<the roster
6346: #                      entry's plan> - (wave 29b, E16) only when the entry names one"] } ] }
6347: # Written under <file>.lock (exclusive open, retried up to 10 s; not acquired = not written) by
6348: # every run that records a provider failure (class operator excepted) or a usable reply
6349: # (Add-MachineHealthRecord: until = a quota's reset time, else the hit + 60 min (10 for a burst);
6350: # an auth failure + 24 h; else null), and by every run while its engine turns run
6351: # (Register-MachineRunning / Unregister-MachineRunning). Every write prunes: an endpoint record
6352: # older than 24 h whose until has passed; a running row whose pid + start time is gone. Read by
6353: # every endpoint-health question (Get-EndpointHealth: every roster walk, the panel selection,
6354: # codex-providers.ps1) and by the panel's scheduler (Get-MachineRunningCount: the endpoint
6355: # parallel limit counts the members of OTHER repositories and panels running on the endpoint -
6356: # (wave 29b, E16) and on any route of the same plan, whatever their engine).
6357: # The file is optional: absent, unreadable or not parseable = as before wave 26b.
6358: 
6359: $script:MachineHealthCache = $null
6360: 
6361: # A running row's start_time as Get-ProcessStartIso writes it (UTC round-trip 'o'), whatever the
6362: # JSON reader made of it (PowerShell 7 turns an ISO text into a [datetime] or [DateTimeOffset]).
6363: function ConvertTo-StartIso {
6364:     param($Value)
6365:     if ($Value -is [DateTimeOffset]) { return $Value.UtcDateTime.ToString('o', $script:Invariant) }
6366:     if ($Value -is [datetime]) { return $Value.ToUniversalTime().ToString('o', $script:Invariant) }
6367:     return [string]$Value
6368: }
