6370: function Get-MachineHealthPath {
6371:     $v = ([string]$env:CODEX_CONSULT_HEALTH).Trim()
6372:     if ($v) { if ($v -ieq 'none') { return '' }; return $v }
6373:     $h = Get-CodexHome
6374:     if (-not $h) { return '' }
6375:     return (Join-Path $h 'codex-consult-health.json')
6376: }
